message.content:
{
  "initial_state": "waking_up",
  "states": [
    {
      "id": "waking_up",
      "description": "Person wakes up, dresses, and stretches in the bedroom.",
      "rules": [],
      "next": [
        {
          "to": "having_breakfast",
          "on": "Person sets a plate of toast on the dining table"
        }
      ]
    },
    {
      "id": "having_breakfast",
      "description": "Person eats breakfast and drinks water at the dining table.",
      "rules": [
        {
          "triggers": [
            "Person checks the phone screen",
            "Person stretches their arms"
          ],
          "action": "Pick up the cup and place it next to the person."
        }
      ],
      "next": [
        {
          "to": "post_breakfast_cleanup",
          "on": "Person is done eating breakfast"
        }
      ]
    },
    {
      "id": "post_breakfast_cleanup",
      "description": "Person cleans up dishes after breakfast.",
      "rules": [
        {
          "triggers": [
            "Person is done eating breakfast",
            "Person leans back in the chair at the table"
          ],
          "action": "Pick up the cup and place it in the dishwasher."
        }
      ],
      "next": [
        {
          "to": "working_at_desk",
          "on": "Person settles into the desk chair"
        }
      ]
    },
    {
      "id": "working_at_desk",
      "description": "Person works on laptop, writes notes, and reads books at the desk.",
      "rules": [
        {
          "triggers": [
            "Person settles into the desk chair",
            "Person opens the laptop"
          ],
          "action": "Pick up the cup and place it next to the person."
        },
        {
          "triggers": [
            "Person closes the laptop",
            "Person stretches"
          ],
          "action": "Pick up the book and place it in the designated storage area."
        }
      ],
      "next": [
        {
          "to": "leaving_house",
          "on": "Person packs a laptop and a notebook into the bag"
        }
      ]
    },
    {
      "id": "leaving_house",
      "description": "Person packs bag and prepares to leave the house.",
      "rules": [
        {
          "triggers": [
            "Person zips the bag closed after packing",
            "Person shoulders their bag"
          ],
          "action": "Turn off the room light."
        }
      ],
      "next": [
        {
          "to": "relaxing_evening",
          "on": "Person arrives home"
        }
      ]
    },
    {
      "id": "relaxing_evening",
      "description": "Person returns home, relaxes on the sofa, and watches TV.",
      "rules": [
        {
          "triggers": [
            "Person watches TV from the sofa",
            "Person relaxes on the sofa"
          ],
          "action": "Pick up the can and place it next to the person."
        }
      ],
      "next": [
        {
          "to": "having_dinner",
          "on": "Person stirs a pot on the stove"
        }
      ]
    },
    {
      "id": "having_dinner",
      "description": "Person cooks and eats dinner at the dining table.",
      "rules": [],
      "next": [
        {
          "to": "post_dinner_cleanup",
          "on": "Person finishes the meal"
        }
      ]
    },
    {
      "id": "post_dinner_cleanup",
      "description": "Person cleans up dishes after dinner.",
      "rules": [
        {
          "triggers": [
            "Person finishes the meal",
            "Person puts down the chopsticks"
          ],
          "action": "Pick up the bowl and place it in the dishwasher."
        }
      ],
      "next": [
        {
          "to": "nighttime_leisure",
          "on": "Person relaxes on the sofa"
        }
      ]
    },
    {
      "id": "nighttime_leisure",
      "description": "Person relaxes on the sofa and watches television in the evening.",
      "rules": [],
      "next": [
        {
          "to": "going_to_sleep",
          "on": "Person clicks the bedside lamp on"
        }
      ]
    },
    {
      "id": "going_to_sleep",
      "description": "Person goes to bed, reads, and prepares to sleep.",
      "rules": [
        {
          "triggers": [
            "Person lies back against the pillow",
            "Person finishes reading and closes the book"
          ],
          "action": "Turn off the bedside lamp."
        }
      ],
      "next": []
    }
  ]
}
